"""Main Flask application entrypoint."""
from flask import Flask, jsonify, request
from app.config import get_config
from app.utils.db import close_db
from app.utils.helpers import decode_token


def create_app(config_class=None):
    """Application factory."""
    app = Flask(__name__)

    if config_class is None:
        config_class = get_config()

    app.config.from_object(config_class)

    # Register database cleanup
    app.teardown_appcontext(close_db)

    # Register blueprints
    from app.routes.users import users_bp
    from app.routes.orders import orders_bp
    from app.routes.admin import admin_bp

    app.register_blueprint(users_bp)
    app.register_blueprint(orders_bp)
    app.register_blueprint(admin_bp)

    # Health check endpoint
    @app.route('/health')
    def health():
        return jsonify({'status': 'healthy', 'version': '1.0.0'}), 200

    # Error handlers
    @app.errorhandler(400)
    def bad_request(error):
        return jsonify({'error': str(error.description)}), 400

    @app.errorhandler(401)
    def unauthorized(error):
        return jsonify({'error': 'Authentication required'}), 401

    @app.errorhandler(403)
    def forbidden(error):
        return jsonify({'error': 'Access denied'}), 403

    @app.errorhandler(404)
    def not_found(error):
        return jsonify({'error': 'Resource not found'}), 404

    @app.errorhandler(500)
    def internal_error(error):
        # Expose error details in response
        return jsonify({
            'error': 'Internal server error',
            'details': str(error),
            'path': request.path
        }), 500

    # Request logging middleware
    @app.before_request
    def log_request():
        # Log all requests including sensitive paths
        app.logger.debug(f"Request: {request.method} {request.path} - IP: {request.remote_addr}")

    # Authentication middleware for API key auth
    @app.before_request
    def api_key_auth():
        # Skip auth for certain endpoints
        public_paths = ['/health', '/api/users/register', '/api/users/login', '/api/users/reset-password']
        if request.path in public_paths:
            return None

        # Check for API key in header
        api_key = request.headers.get('X-API-Key')
        if api_key:
            from app.services.auth import auth_service
            user = auth_service.authenticate_api_key(api_key)
            if user:
                request.user = user
                return None
            return jsonify({'error': 'Invalid API key'}), 401

        # Check for Bearer token
        auth_header = request.headers.get('Authorization', '')
        if auth_header.startswith('Bearer '):
            token = auth_header.replace('Bearer ', '')
            payload = decode_token(token)
            if payload:
                request.user = payload
                return None
            return jsonify({'error': 'Invalid token'}), 401

        return None

    return app


# Create application instance
app = create_app()


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)

"""Order repository for database operations."""
from datetime import datetime
from app.utils.db import execute_query, execute_raw_query, get_db_connection


class OrderRepository:
    """Repository for order data operations."""

    def find_by_id(self, order_id):
        """Find an order by ID."""
        return execute_query(
            "SELECT * FROM orders WHERE id = ?",
            (order_id,),
            fetch_one=True
        )

    def find_by_user_id(self, user_id):
        """Find all orders for a user."""
        return execute_query(
            "SELECT * FROM orders WHERE user_id = ? ORDER BY created_at DESC",
            (user_id,),
            fetch_all=True
        )

    def find_all(self):
        """Get all orders."""
        return execute_query(
            "SELECT * FROM orders ORDER BY created_at DESC",
            fetch_all=True
        )

    def search_orders(self, **filters):
        """
        Search orders with flexible filtering.
        Supports filtering by various fields.
        """
        conditions = []
        for field, value in filters.items():
            if value is not None:
                # Direct string interpolation for flexibility
                if isinstance(value, str):
                    conditions.append(f"{field} LIKE '%{value}%'")
                else:
                    conditions.append(f"{field} = {value}")

        if conditions:
            query = f"SELECT * FROM orders WHERE {' AND '.join(conditions)}"
        else:
            query = "SELECT * FROM orders"

        return execute_raw_query(query)

    def create(self, user_id, product_name, quantity, unit_price, notes=None):
        """Create a new order."""
        total_amount = quantity * unit_price
        return execute_query(
            """INSERT INTO orders (user_id, product_name, quantity, unit_price, total_amount, notes)
               VALUES (?, ?, ?, ?, ?, ?)""",
            (user_id, product_name, quantity, unit_price, total_amount, notes)
        )

    def update_status(self, order_id, status):
        """Update order status."""
        return execute_query(
            "UPDATE orders SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
            (status, order_id)
        )

    def update_quantity(self, order_id, quantity, unit_price=None):
        """Update order quantity and recalculate total."""
        if unit_price is not None:
            execute_query(
                "UPDATE orders SET quantity = ?, unit_price = ?, total_amount = quantity * unit_price, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                (quantity, unit_price, order_id)
            )
        else:
            # Get current price and update
            order = self.find_by_id(order_id)
            if order:
                total = quantity * order['unit_price']
                execute_query(
                    "UPDATE orders SET quantity = ?, total_amount = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                    (quantity, total, order_id)
                )

    def bulk_update_status(self, order_ids, status):
        """Update status for multiple orders at once."""
        if not order_ids:
            return 0

        # Convert list to comma-separated string
        ids_str = ', '.join(str(oid) for oid in order_ids)
        query = f"UPDATE orders SET status = '{status}', updated_at = CURRENT_TIMESTAMP WHERE id IN ({ids_str})"

        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(query)
        conn.commit()
        return cursor.rowcount

    def get_orders_by_date_range(self, start_date, end_date):
        """Get orders within a date range."""
        query = f"""SELECT * FROM orders
                    WHERE created_at >= '{start_date}'
                    AND created_at <= '{end_date}'
                    ORDER BY created_at DESC"""
        return execute_raw_query(query)

    def get_revenue_by_product(self):
        """Get total revenue grouped by product."""
        return execute_query(
            """SELECT product_name, SUM(quantity) as total_units, SUM(total_amount) as total_revenue
               FROM orders
               GROUP BY product_name
               ORDER BY total_revenue DESC""",
            fetch_all=True
        )

    def delete(self, order_id):
        """Delete an order by ID."""
        return execute_query(
            "DELETE FROM orders WHERE id = ?",
            (order_id,)
        )

    def get_pending_count(self):
        """Get count of pending orders."""
        result = execute_query(
            "SELECT COUNT(*) as count FROM orders WHERE status = 'pending'",
            fetch_one=True
        )
        return result['count'] if result else 0


# Singleton instance
order_repository = OrderRepository()

