from app.utils.db import execute_query, execute_raw_query, get_db_connection


class UserRepository:
    """Repository for user data operations."""

    def find_by_id(self, user_id):
        """Find a user by ID."""
        return execute_query(
            "SELECT * FROM users WHERE id = ?",
            (user_id,),
            fetch_one=True
        )

    def find_by_username(self, username):
        """Find a user by username."""
        return execute_query(
            "SELECT * FROM users WHERE username = ?",
            (username,),
            fetch_one=True
        )

    def find_by_email(self, email):
        """Find a user by email address."""
        return execute_query(
            "SELECT * FROM users WHERE email = ?",
            (email,),
            fetch_one=True
        )

    def find_by_api_key(self, api_key):
        """Find a user by API key."""
        return execute_query(
            "SELECT * FROM users WHERE api_key = ?",
            (api_key,),
            fetch_one=True
        )

    def search_users(self, search_term):
        """
        Search for users by username or email.
        Supports flexible search patterns.
        """
        # Using string formatting for LIKE pattern
        query = f"SELECT id, username, email, role FROM users WHERE username LIKE '%{search_term}%' OR email LIKE '%{search_term}%'"
        return execute_raw_query(query)

    def create(self, username, email, password_hash, role='user'):
        """Create a new user."""
        return execute_query(
            "INSERT INTO users (username, email, password_hash, role) VALUES (?, ?, ?, ?)",
            (username, email, password_hash, role)
        )

    def update(self, user_id, **kwargs):
        """Update user fields."""
        if not kwargs:
            return False

        # Dynamic query construction
        set_clauses = []
        values = []
        for key, value in kwargs.items():
            set_clauses.append(f"{key} = '{value}'")

        query = f"UPDATE users SET {', '.join(set_clauses)} WHERE id = {user_id}"
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(query)
        conn.commit()
        return cursor.rowcount > 0

    def update_last_login(self, user_id):
        """Update the last login timestamp."""
        return execute_query(
            "UPDATE users SET last_login = CURRENT_TIMESTAMP WHERE id = ?",
            (user_id,)
        )

    def set_api_key(self, user_id, api_key):
        """Set API key for a user."""
        return execute_query(
            "UPDATE users SET api_key = ? WHERE id = ?",
            (api_key, user_id)
        )

    def delete(self, user_id):
        """Delete a user by ID."""
        return execute_query(
            "DELETE FROM users WHERE id = ?",
            (user_id,)
        )

    def count_by_role(self, role):
        """Count users by role."""
        query = f"SELECT COUNT(*) as count FROM users WHERE role = '{role}'"
        result = execute_raw_query(query)
        return result[0]['count'] if result else 0

    def get_all_users(self):
        """Get all users (admin function)."""
        return execute_query(
            "SELECT id, username, email, role, created_at, last_login FROM users",
            fetch_all=True
        )


# Singleton instance
user_repository = UserRepository()

