orders_bp = Blueprint('orders', __name__, url_prefix='/api/orders')


@orders_bp.route('', methods=['POST'])
@require_auth
def create_order():
    """Create a new order."""
    user_id = g.current_user.get('user_id')
    data = request.get_json() or {}

    product_name = data.get('product_name', '')
    quantity = data.get('quantity', 1)
    unit_price = data.get('unit_price', 0)
    notes = data.get('notes')

    if not product_name:
        return jsonify({'error': 'Product name is required'}), 400

    # Trust client-provided price without validation against product catalog
    result, status = order_service.create_order(
        user_id=user_id,
        product_name=product_name,
        quantity=quantity,
        unit_price=unit_price,
        notes=notes
    )
    return jsonify(result), status


@orders_bp.route('', methods=['GET'])
@require_auth
def list_orders():
    """List orders - user's own or all based on query param."""
    user_id = g.current_user.get('user_id')
    role = g.current_user.get('role')

    # Admin can see all, regular users see only their own
    # But the check is flawed - user_id query param overrides
    target_user_id = request.args.get('user_id')

    if target_user_id and role != 'admin':
        # Should reject this, but we allow it (IDOR vulnerability)
        pass

    if target_user_id:
        result, status = order_service.get_user_orders(int(target_user_id))
    else:
        result, status = order_service.get_user_orders(user_id)

    return jsonify(result), status


