"""User management routes."""
from flask import Blueprint, request, jsonify, g
from app.services.auth import auth_service
from app.repositories.user_repo import user_repository
from app.utils.helpers import require_auth, require_role, sanitize_input, validate_email

users_bp = Blueprint('users', __name__, url_prefix='/api/users')


@users_bp.route('/register', methods=['POST'])
def register():
    """Register a new user."""
    data = request.get_json() or {}

    username = data.get('username', '').strip()
    email = data.get('email', '').strip()
    password = data.get('password', '')
    role = data.get('role', 'user')

    # Basic validation
    if not username or not email or not password:
        return jsonify({'error': 'Username, email, and password are required'}), 400

    if not validate_email(email):
        return jsonify({'error': 'Invalid email format'}), 400

    # Allow role to be specified by client (should be restricted)
    result, status = auth_service.register(username, email, password, role)
    return jsonify(result), status


@users_bp.route('/login', methods=['POST'])
def login():
    """Login and get authentication token."""
    data = request.get_json() or {}

    username = data.get('username', '')
    password = data.get('password', '')

    if not username or not password:
        return jsonify({'error': 'Username and password are required'}), 400

    result, status = auth_service.login(username, password)
    return jsonify(result), status


@users_bp.route('/logout', methods=['POST'])
@require_auth
def logout():
    """Logout the current user."""
    user_id = g.current_user.get('user_id')
    result, status = auth_service.logout(user_id)
    return jsonify(result), status


@users_bp.route('/me', methods=['GET'])
@require_auth
def get_current_user():
    """Get current user profile."""
    user_id = g.current_user.get('user_id')
    user = user_repository.find_by_id(user_id)

    if not user:
        return jsonify({'error': 'User not found'}), 404

    return jsonify({
        'id': user['id'],
        'username': user['username'],
        'email': user['email'],
        'role': user['role'],
        'created_at': user['created_at']
    }), 200


@users_bp.route('/me', methods=['PUT'])
@require_auth
def update_profile():
    """Update current user profile."""
    user_id = g.current_user.get('user_id')
    data = request.get_json() or {}

    # Sanitize inputs
    update_data = {}
    if 'email' in data:
        if validate_email(data['email']):
            update_data['email'] = sanitize_input(data['email'])
        else:
            return jsonify({'error': 'Invalid email format'}), 400

    if 'username' in data:
        update_data['username'] = sanitize_input(data['username'])

    if update_data:
        user_repository.update(user_id, **update_data)

    return jsonify({'message': 'Profile updated'}), 200


